public class FirstLastOccurrence { public static void main(String[] args) { int[] arr = {10,20,20,20,30,40}; int target = 20; int first = -1; int last = -1; int low = 0; int high = arr.length - 1; while (low <= high) { int mid = (low + high) / 2; if (arr[mid] == target) { first = mid; high = mid - 1; } else if (arr[mid] < target) { low = mid + 1; } else { high = mid - 1; } } low = 0; high = arr.length - 1; while (low <= high) { int mid = (low + high) / 2; if (arr[mid] == target) { last = mid; low = mid + 1; } else if (arr[mid] < target) { low = mid + 1; } else { high = mid - 1; } } System.out.println("First occurrence = " + first); System.out.println("Last occurrence = " + last); } }
